WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_base_calc'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '基期量计算', 'kp-xingce-data-base-calc', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "基期量计算"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "已知当前数据和变化幅度，逆向倒推历史数据的除法运算。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干给的是 2024 年的数据，问的是 2023 年（或更早）的数据。特征：时间前移 + 求具体数值（带有单位）。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "基期量 = \\frac{现期量}{1 + 增长率}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干时间与材料时间比对] --> B{时间是否前移?}\nB -- 是 --> C[确认选项带有单位（求量）]\nC --> D[回材料找对应的现期量和增长率 r]\nD --> E[列出除法式子: 现期量 / (1+r)]\nE --> F[采用截位直除法估算分母, 求出商]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年全国夏粮产量 14613 万吨，比上年下降 0.9%。问：2022年全国夏粮产量约为多少万吨？选项：A. 14480 B. 14613 C. 14745 D. 14890"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：时间为2022年（前移），单位为万吨（求量），判定为基期量计算。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列式：因为是下降，公式为 现期量 / (1 - 减少率) = 14613 / (1 - 0.9%)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "代数：14613 / 0.991。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "截位直除：选项差距尚可，分母保留三位有效数字。14613 ÷ 991。商首位1，次位4，第三位7。结果序列为 147...。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分母符号加减混乱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "材料说“下降了 x%”，分母必须是 1 - x%。考场上非常容易紧张下一律按 1 + x% 去算。另一个坑是找错“现期量”的主体，棉花和夏粮张冠李戴。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "基期量是资料分析得分的基本盘。建议每天做 5 道基期量计算，专门练习“看到下降就写减号”和“截位直除留三位”的肌肉反应。"}]}]}$$ AS jsonb), NULL, '基期量计算的核心考点与实战推导。', category_node.id, CAST('["资料分析", "基期量计算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_base_calc", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
